<?php
declare(strict_types=1);
defined('ABSPATH') || exit;

$page_fields = function_exists('get_fields') ? (get_fields() ?: []) : [];
$_page_sections = [
    'banner' => is_array($page_fields['banner_settings'] ?? null) ? $page_fields['banner_settings'] : [],
    'intro' => is_array($page_fields['intro_settings'] ?? null) ? $page_fields['intro_settings'] : [],
    'timeline' => is_array($page_fields['timeline_settings'] ?? null) ? $page_fields['timeline_settings'] : [],
    'values' => is_array($page_fields['values_settings'] ?? null) ? $page_fields['values_settings'] : [],
    'team' => is_array($page_fields['team_settings'] ?? null) ? $page_fields['team_settings'] : [],
    'videos' => is_array($page_fields['videos_settings'] ?? null) ? $page_fields['videos_settings'] : [],
];
$section_enabled = 'underscores_child_section_is_visible';
$banner_settings = $_page_sections['banner'];
$intro_settings = $_page_sections['intro'];
$timeline_settings = $_page_sections['timeline'];
$values_settings = $_page_sections['values'];
$team_settings = $_page_sections['team'];
$videos_settings = $_page_sections['videos'];

